  "Peticiones que se envían solas al chat de este proyecto, como si las escribieras tú: pasan por el plan, los agentes y la verificación. Se lanzan a una hora, al llegar un webhook o al cambiar archivos, mientras kywai esté abierto en el servidor. Nunca hay dos a la vez de la misma rutina. También puedes escribir": "Solicitações que são enviadas sozinhas ao chat deste projeto, como se você as digitasse: passam pelo plano, pelos agentes e pela verificação. Rodam num horário, quando chega um webhook ou quando arquivos mudam, enquanto o kywai estiver aberto no servidor. Duas execuções da mesma rotina nunca se sobrepõem. Você também pode digitar",
