  "Busca una canción o un artista, o pega un enlace de YouTube. Sin anuncios: Audius (música que suben los propios artistas) y las radios de SomaFM. Las luces del espacio siguen su ritmo, sin usar el micrófono.": "Pesquise uma música ou um artista, ou cole um link do YouTube. Sem anúncios: Audius (música enviada pelos próprios artistas) e as rádios do SomaFM. As luzes do espaço seguem o ritmo, sem usar o microfone.",
