  "Radios": "Rádios",
  "Con Audius y las radios, las luces escuchan el sonido directamente: no hace falta compartir nada.": "Com Audius e as rádios, as luzes ouvem o som diretamente: não é preciso compartilhar nada.",
  "Con Audius y las radios, las luces escuchan el sonido de verdad: llega directamente a kywai, sin micrófono y sin compartir nada.": "Com Audius e as rádios, as luzes ouvem o som de verdade: ele chega direto ao kywai, sem microfone e sem compartilhar nada.",
  "YouTube exige que su reproductor esté a la vista: al cerrar este panel la música se pausa. Mientras suena cualquier fuente, sustituye a la música ambiental de kywai.": "O YouTube exige que o player esteja visível: fechar este painel pausa a música. Enquanto qualquer fonte toca, substitui a música ambiente do kywai.",
