  "Es una estimación: no se escucha ni se analiza el audio (YouTube no lo permite y no se usa el micrófono). Se usa el BPM publicado de la canción (Deezer) y la posición del reproductor.": "É uma estimativa: o áudio não é escutado nem analisado (o YouTube não permite e o microfone não é usado). Usa o BPM publicado da música (Deezer) e a posição do player.",
  "Se ajusta solo al pausar, reanudar, saltar o cambiar la velocidad. El primer pulso no se conoce: si las luces van desplazadas, usa «Marcar pulso» o el desfase.": "Reajusta sozinho quando você pausa, retoma, pula ou muda a velocidade. A primeira batida não é conhecida: se as luzes estiverem fora, use «Marcar ritmo» ou a defasagem.",
  "Las canciones en directo, con tempo variable, remezclas o vídeos con introducción pueden desalinearse.": "Músicas ao vivo, com tempo variável, remixes ou vídeos com introdução podem sair de sincronia.",
