  "Tiempo (mediana)": "Tempo (mediana)",
  "Tokens (mediana)": "Tokens (mediana)",
  "Lo que te sirvió, lo que pasó la verificación de otro agente a la primera o tras corregir, lo que no la superó, lo que quedó sin verificar y lo que falló. Por agente y por dificultad.": "O que foi útil para você, o que passou na verificação de outro agente na primeira ou após corrigir, o que não passou, o que ficou sem verificar e o que falhou. Por agente e por dificuldade.",
  "Todavía no hay tareas en este periodo. Cada tarea que haga un agente cuenta aquí en cuanto termine.": "Ainda não há tarefas neste período. Cada tarefa que um agente faz conta aqui assim que termina.",
  "De las que valoraste con 👍/👎, las que te sirvieron": "Das que você avaliou com 👍/👎, as que foram úteis",
  "Le sirvió 👍": "Úteis 👍",
  "De las que comprobó otro agente, las que cumplían a la primera": "Das que outro agente verificou, as que passaram na primeira",
  "De las que comprobó otro agente, las que tuvo que corregir": "Das que outro agente verificou, as que ele precisou corrigir",
  "De las que comprobó otro agente con fallos, las que pasaron tras corregirlas": "Das que outro agente verificou com falhas, as que passaram após corrigir",
  "De las que comprobó otro agente, las que acabaron con fallos (relevo o «requiere intervención»)": "Das que outro agente verificou, as que terminaram com falhas (repasse ou «requer intervenção»)",
  "El verificador no dio un veredicto claro ni al pedírselo otra vez: ni aprobada ni suspendida": "O verificador não deu um veredito claro mesmo pedindo de novo: nem passou nem falhou",
  "No pudo hacerla, o la terminó otro agente": "Não conseguiu, ou outro agente terminou",
  "pocos datos": "poucos dados",
  "Cada tarea cuenta una vez por agente, aunque tuviera varios intentos o una corrección (su tiempo y sus tokens se suman). «Le sirvió» sale de tus 👍/👎 en el chat; «verificada» y «corrección», de la comprobación por otro agente (solo las tareas que cambian archivos). Las tareas que detuviste no cuentan. «Sin dato»: tareas anteriores a que se guardara la dificultad.": "Cada tarefa conta uma vez por agente, mesmo que tenha tido várias tentativas ou uma correção (seu tempo e tokens se somam). «Úteis» vem do seu 👍/👎 no chat; «verificadas» e «correção», da revisão de outro agente (só tarefas que mudam arquivos). As tarefas que você parou não contam. «Sem dados»: tarefas de antes de se guardar a dificuldade.",
  "El coordinador ve estas cifras en la ficha de cada agente cuando tiene": "O coordenador vê estes números no perfil de cada agente quando ele tem",
  "tareas o más en 30 días, y las usa al repartir: la calidad pesa más que la velocidad y el coste.": "tarefas ou mais em 30 dias, e os usa ao atribuir: a qualidade pesa mais que a velocidade e o custo.",
