  "5 veces la cuota de Sol sin mejorarlo": "5 vezes a cota do Sol sem superá-lo",
  "El mejor Gemini para código; tiene nivel gratuito": "O melhor Gemini para código; tem nível gratuito",
  "Muy rápido y barato": "Muito rápido e barato",
  "Rápido; flojo programando": "Rápido; fraco em código",
  "Solo con clave de pago; lee documentos enormes": "Só com chave paga; lê documentos enormes",
  "Con clave gratuita puede intentar Pro (de pago)": "Com chave gratuita pode tentar o Pro (pago)",
  "El de Muse Code": "O próprio do Muse Code",
  "El que tenga configurado (respeta el modo Contributor)": "O que estiver configurado (respeita o modo Contributor)",
  "El más nuevo: mejor en trabajo largo y gasta menos tokens": "O mais novo: melhor em trabalho longo e gasta menos tokens",
