  "Los hooks y los servidores de lenguaje de un plugin no se instalan (los cambios de comportamiento llegarán con los mods). Los servidores MCP que solo admiten iniciar sesión en el navegador tampoco: aún no se pueden usar en las tareas.": "Os hooks e os servidores de linguagem de um plugin não são instalados (as mudanças de comportamento virão com os mods). Os servidores MCP que só aceitam login pelo navegador também não: ainda não podem ser usados nas tarefas.",
