  "Ese plugin ya no está": "Esse plugin não está mais lá",
  'Agente de programación de código abierto de Kilo en la terminal, con cientos de modelos y varios gratuitos.': 'Agente de programação de código aberto da Kilo no terminal, com centenas de modelos e vários gratuitos.',
  'Sin cuenta con sus modelos gratuitos; con tu cuenta de Kilo (kilo auth login) para los de pago, o tus propias claves de API.': 'Sem conta com os modelos gratuitos; com a sua conta da Kilo (kilo auth login) para os pagos, ou as suas próprias chaves de API.',
  'Agente conectado: programa en la terminal con los modelos de Kilo (gratuitos o de tu cuenta)': 'Agente conectado: programa no terminal com os modelos da Kilo (gratuitos ou da sua conta)',
  'Empieza con el modelo gratuito Kilo Auto Free (kilo/kilo-auto/free): sin él, su modelo por defecto es de pago y pide cuenta. Los gratuitos cambian cuando acaban sus promociones; la lista sale con «kilo models kilo».': 'Começa com o modelo gratuito Kilo Auto Free (kilo/kilo-auto/free): sem ele, o modelo padrão é pago e pede conta. Os gratuitos mudam quando terminam as promoções; a lista sai com «kilo models kilo».',
  'Gratis': 'Grátis',
  'Solo gratis': 'Só grátis',
  'Solo los que se pueden usar sin pagar una suscripción': 'Só os que podem ser usados sem pagar uma assinatura',
  'Ningún agente gratis coincide. Quita «Solo gratis» para ver todos.': 'Nenhum agente grátis corresponde. Desative «Só grátis» para ver todos.',
  'Ya tienes en tu equipo todos los agentes gratis del catálogo.': 'Você já tem na sua equipe todos os agentes grátis do catálogo.',
  'Gratis: funciona en tu propio equipo, sin cuenta ni límites.': 'Grátis: funciona no seu próprio computador, sem conta nem limites.',
  'Gratis con una clave de OpenRouter y sus modelos «:free»: unas 50 peticiones al día (1000 si alguna vez compraste 10 $ de saldo).': 'Grátis com uma chave da OpenRouter e os modelos «:free»: cerca de 50 pedidos por dia (1000 se alguma vez comprou 10 $ de saldo).',
  'Gratis con una clave de API de Google AI Studio: sin tarjeta, solo modelos Flash y unas 250 peticiones al día. Google usa lo que le envías para mejorar sus productos.': 'Grátis com uma chave de API do Google AI Studio: sem cartão, só modelos Flash e cerca de 250 pedidos por dia. O Google usa o que você envia para melhorar os seus produtos.',
  'Gratis con una clave de OpenRouter y uno de sus modelos «:free»: unas 50 peticiones al día (1000 si alguna vez compraste 10 $ de saldo).': 'Grátis com uma chave da OpenRouter e um dos modelos «:free»: cerca de 50 pedidos por dia (1000 se alguma vez comprou 10 $ de saldo).',
  'Gratis con los modelos gratuitos de OpenCode Zen, que solo funcionan desde OpenCode: el límite se reparte entre todos sus usuarios y algunos usan lo que envías para entrenar.': 'Grátis com os modelos gratuitos do OpenCode Zen, que só funcionam a partir do OpenCode: o limite é dividido entre todos os usuários e alguns usam o que você envia para treinar.',
  'Gratis con el plan Copilot Free de GitHub, que incluye Copilot CLI con un cupo mensual pequeño.': 'Grátis com o plano Copilot Free do GitHub, que inclui o Copilot CLI com uma cota mensal pequena.',
  'Gratis con una clave del plan gratuito de Mistral (Experiment), con límites bajos y pensado para probar.': 'Grátis com uma chave do plano gratuito da Mistral (Experiment), com limites baixos e pensado para testar.',
  'Gratis con los modelos marcados como FREE en tu cuenta de Cline.': 'Grátis com os modelos marcados como FREE na sua conta da Cline.',
  'Gratis con tu cuenta personal de Google, con un límite semanal (lee la nota sobre sus condiciones).': 'Grátis com a sua conta pessoal do Google, com um limite semanal (leia a nota sobre as condições).',
  'Gratis, sin tarjeta y sin cuenta, con sus modelos gratuitos (empieza con Kilo Auto Free).': 'Grátis, sem cartão e sem conta, com os modelos gratuitos (começa com o Kilo Auto Free).',
  '¿No pagas ninguna suscripción? Así puedes usar kywai gratis': 'Não paga nenhuma assinatura? Veja como usar o kywai de graça',
  'Los agentes con la etiqueta «Gratis» funcionan sin suscripción de pago, cada uno con su límite. Para empezar:': 'Os agentes com a etiqueta «Grátis» funcionam sem assinatura paga, cada um com o seu limite. Para começar:',
  'Para trabajar': 'Para trabalhar',
  'Kilo CLI, gratis y sin cuenta; también OpenCode, Copilot CLI (con Copilot Free) o Cline.': 'Kilo CLI, grátis e sem conta; também OpenCode, Copilot CLI (com o Copilot Free) ou Cline.',
  'Ver los agentes gratis': 'Ver os agentes grátis',
  'con una clave gratis de Google AI Studio (sin tarjeta). Pégala en el paso «Sesiones».': 'com uma chave grátis do Google AI Studio (sem cartão). Cole-a na etapa «Sessões».',
  'Conseguir la clave': 'Obter a chave',
  'Para coordinar (Hermes)': 'Para coordenar (Hermes)',
  'con una clave gratis de OpenRouter. En «Sesiones», pulsa «Configurar» en Hermes, elige OpenRouter y un modelo que acabe en «:free» (unas 50 peticiones al día).': 'com uma chave grátis da OpenRouter. Em «Sessões», toque em «Configurar» no Hermes, escolha a OpenRouter e um modelo que termine em «:free» (cerca de 50 pedidos por dia).',
  'siempre gratis y sin límites, con LM Studio u Ollama en tu propio equipo.': 'sempre grátis e sem limites, com LM Studio ou Ollama no seu próprio computador.',
  "Mods": "Mods",
  "El panel «{panel}» quiere enviar al chat:\n\n{text}": "O painel “{panel}” quer enviar ao chat:\n\n{text}",
  "Ningún mod encendido tiene paneles. Instálalos en ⚙ → Ajustes → Extensiones → Mods.": "Nenhum mod ligado tem painéis. Instale-os em ⚙ → Ajustes → Extensões → Mods.",
  "Paneles de los mods": "Painéis dos mods",
  "Panel del mod «{mod}». Funciona en una caja aislada: no puede tocar el resto de kywai.": "Painel do mod “{mod}”. Funciona numa caixa isolada: não pode mexer no resto do kywai.",
  "Cambian kywai en sí: órdenes «/algo» para el chat, hooks que hacen algo al empezar o acabar una petición o una tarea, y paneles que se abren junto al chat (pestaña «Mods»). Cada mod es una carpeta con su kywai-mod.json.": "Mudam o próprio kywai: comandos “/algo” para o chat, hooks que fazem algo ao começar ou terminar um pedido ou uma tarefa, e painéis que abrem ao lado do chat (aba “Mods”). Cada mod é uma pasta com seu kywai-mod.json.",
