  "Revisa el pull request {pr}: explica qué cambia, busca fallos, riesgos de seguridad y casos sin probar, y termina con una lista de cambios recomendados, de más a menos importante. No cambies nada del repositorio.": "Revise o pull request {pr}: explique o que muda, procure erros, riscos de segurança e casos sem teste, e termine com uma lista de mudanças recomendadas, da mais para a menos importante. Não altere nada no repositório.",
  "Resumir carpeta": "Resumir pasta",
  "resumir-carpeta": "resumir-pasta",
  "Lee la carpeta {slot} del proyecto y resume qué contiene: para qué sirve cada parte, cuáles son los archivos más importantes y qué parece que falta o está a medias.": "Leia a pasta {slot} do projeto e resuma o que ela contém: para que serve cada parte, quais são os arquivos mais importantes e o que parece faltar ou estar pela metade.",
