  "Busca fallos en {slot}: errores de lógica, casos límite sin tratar y mensajes de error confusos. De cada uno di dónde está, cómo reproducirlo y cómo arreglarlo.": "Procure erros em {slot}: erros de lógica, casos-limite não tratados e mensagens de erro confusas. Para cada um, diga onde está, como reproduzi-lo e como corrigi-lo.",
  "qué-revisar": "o-que-revisar",
  "Escribir pruebas": "Escrever testes",
  "escribir-pruebas": "escrever-testes",
  "Escribe pruebas automáticas para {slot} con el sistema de pruebas que ya use el proyecto, cubre los casos normales y los límite, y ejecútalas para comprobar que pasan.": "Escreva testes automatizados para {slot} com o sistema de testes que o projeto já usa, cubra os casos normais e os limites, e execute-os para verificar que passam.",
  "qué-probar": "o-que-testar",
  "Actualizar dependencias": "Atualizar dependências",
  "actualizar-dependencias": "atualizar-dependencias",
  "Revisa las dependencias del proyecto: cuáles están desactualizadas o tienen fallos de seguridad conocidos. Actualiza las que sea seguro actualizar, ejecuta las pruebas y explica qué has cambiado, qué has dejado sin tocar y por qué.": "Revise as dependências do projeto: quais estão desatualizadas ou têm falhas de segurança conhecidas. Atualize as que for seguro atualizar, execute os testes e explique o que mudou, o que deixou sem mexer e por quê.",
  "Explicar código": "Explicar código",
  "explicar-codigo": "explicar-codigo",
