  "Instalada: cada frase suena alegre, triste o emocionada, con el timbre de la voz elegida": "Instalada: cada frase soa alegre, triste ou animada, com o timbre da voz escolhida",
  "Falta: «Instalar lo que falta» la instala (unos 5 GB con el modelo); mientras, la voz va sin emoción": "Falta: «Instalar o que falta» instala-a (cerca de 5 GB com o modelo); até lá, a voz fica sem emoção",
  "Diálogo": "Diálogo",
  "Quién habla": "Quem fala",
