  "Un narrador o el presentador": "Um narrador ou o apresentador",
  "Dos personajes que se contestan, cada uno con su voz": "Duas personagens que se respondem, cada uma com a sua voz",
  "Voz de ElevenLabs (de pago)": "Voz da ElevenLabs (paga)",
  "Crea una cuenta en elevenlabs.io (el plan gratis trae 10.000 caracteres al mes; un reel de un minuto gasta unos 1.000).": "Crie uma conta em elevenlabs.io (o plano grátis inclui 10.000 caracteres por mês; um reel de um minuto gasta cerca de 1.000).",
  "Abrir ElevenLabs": "Abrir ElevenLabs",
  "En tu perfil → API Keys, pulsa «Create API Key», dale permiso de «Text to Speech» y de leer «Voices», y copia la clave (empieza por sk_).": "No seu perfil → API Keys, clique em «Create API Key», dê acesso a «Text to Speech» e leitura de «Voices», e copie a chave (começa por sk_).",
  "Pégala aquí abajo y pulsa «Conectar». Si quieres más voces, añádelas a tu cuenta desde la biblioteca de voces de ElevenLabs: salen solas en /video.": "Cole-a abaixo e clique em «Conectar». Se quiser mais vozes, adicione-as à sua conta pela biblioteca de vozes da ElevenLabs: aparecem sozinhas em /video.",
  "No compartas la clave con nadie (tampoco en un chat): kywai la guarda cifrada en este equipo.": "Não partilhe a chave com ninguém (nem num chat): o kywai guarda-a cifrada neste computador.",
  "Las voces de ElevenLabs (modelo v3) actúan cada frase: alegres, tristes, susurrando o riéndose, y hacen diálogos de dos personajes. Con la clave, salen en el paso «Voz» de /video junto a las gratis para que compares con el mismo guion.": "As vozes da ElevenLabs (modelo v3) interpretam cada frase: alegres, tristes, sussurrando ou rindo, e fazem diálogos de duas personagens. Com a chave, aparecem no passo «Voz» de /video junto às grátis para comparar com o mesmo roteiro.",
  "Te quedan {n} caracteres este mes": "Restam {n} caracteres este mês",
  "Sus voces ya salen en /video": "As vozes já aparecem em /video",
  "Clave de API (sk_…)": "Chave de API (sk_…)",
  "Clave de API de ElevenLabs": "Chave de API da ElevenLabs",
  "Pega la clave de API de ElevenLabs": "Cole a chave de API da ElevenLabs",
  "Falta la clave de ElevenLabs: pégala en Ajustes → Extensiones → Estudio de vídeo": "Falta a chave da ElevenLabs: cole-a em Definições → Extensões → Estúdio de vídeo",
  "ElevenLabs no devolvió la muestra: mira la clave y los caracteres que te quedan": "A ElevenLabs não devolveu a amostra: verifique a chave e os caracteres que restam",
  "ElevenLabs v3": "ElevenLabs v3",
  "La que más actúa: de pago, con tu clave.": "A mais expressiva: paga, com a sua chave.",
  "Con una clave de ElevenLabs (Ajustes → Extensiones → Estudio de vídeo) tendrás sus voces, las que más actúan.": "Com uma chave da ElevenLabs (Definições → Extensões → Estúdio de vídeo) terá as vozes dela, as mais expressivas.",
  "Kokoro: natural, gratis y en este equipo": "Kokoro: natural, grátis e neste computador",
  "La del sistema (instala Kokoro para una más natural)": "A do sistema (instale Kokoro para uma mais natural)",
  "Sin voz": "Sem voz",
  "Imágenes": "Imagens",
  "Escribe «/video» y el tema, o «créame un vídeo de…», o pulsa «Crear vídeo de esto» bajo un mensaje. Un agente escribe el guion y kywai pone la voz, las imágenes, la música, las animaciones y el montaje. Solo te llega el vídeo; el material de trabajo queda guardado en la carpeta oculta .ai-cowork/videos del proyecto. Para TikTok, Reels o Shorts, di «vertical».": "Escreva «/video» e o tema, ou «cria-me um vídeo sobre…», ou toque em «Criar vídeo disto» por baixo de uma mensagem. Um agente escreve o guião e o kywai põe a voz, as imagens, a música, as animações e a montagem. Só recebe o vídeo; o material de trabalho fica na pasta oculta .ai-cowork/videos do projeto. Para TikTok, Reels ou Shorts, diga «vertical».",
  "Instalando… (puede tardar varios minutos)": "A instalar… (pode demorar vários minutos)",
  "Comprobar e instalar otra vez": "Verificar e instalar de novo",
  "Instalar lo que falta": "Instalar o que falta",
  "No encuentro ese mensaje para hacer el vídeo": "Não encontro essa mensagem para fazer o vídeo",
  "¿De qué hago el vídeo? Escribe el tema («/video cómo funciona la fotosíntesis») o pulsa «Crear vídeo de esto» en un mensaje.": "De que faço o vídeo? Escreva o tema («/video como funciona a fotossíntese») ou toque em «Criar vídeo disto» numa mensagem.",
  "Crea un vídeo de este mensaje: «{text}»": "Cria um vídeo desta mensagem: «{text}»",
