  "Descarga el motor y el modelo recomendado para este equipo (19 GB o más, puede tardar horas; si se corta, vuelve a pulsar y sigue). Pulsa otra vez para empezar.": "Baixa o motor e o modelo recomendado para este computador (19 GB ou mais, pode levar horas; se parar, toque de novo e continua). Toque outra vez para começar.",
  "kywai lo instala con el modelo que mejor cabe en este equipo. También puedes escribir abajo la dirección de otro servidor compatible con OpenAI.": "O kywai instala com o modelo que melhor cabe neste computador. Também pode escrever abaixo o endereço de outro servidor compatível com a OpenAI.",
