  "Los estilos de película los dirige un agente con terminal y tardan más (de 20 minutos a una hora). Muestras: películas de ejemplo de Lemo-Opuscar (CC BY 4.0); en los estilos de kywai, fotogramas hechos por kywai.": "Os estilos de filme são dirigidos por um agente com terminal e demoram mais (de 20 minutos a uma hora). Amostras: filmes de exemplo do Lemo-Opuscar (CC BY 4.0); nos estilos do kywai, quadros feitos pelo kywai.",
