  "Al abrirla la primera vez pide crear tu propia app gratis de Spotify y una cuenta Premium. Luego vuelve aquí.": "Na primeira vez pede para criares a tua própria app gratuita do Spotify e uma conta Premium. Depois volta aqui.",
