  "Spotifast no ha respondido al abrirla. Ábrela a mano e inicia sesión en ella.": "O Spotifast não respondeu ao abrir. Abre-o à mão e inicia sessão.",
  "Spotifast no pudo ponerlo. Mira que hayas iniciado sesión con Spotify Premium en ella.": "O Spotifast não conseguiu tocar. Confirma que iniciaste sessão com Spotify Premium.",
  "Spotify con tu cuenta Premium, en la app Spotifast: kywai la maneja desde aquí": "Spotify com a tua conta Premium, na app Spotifast: o kywai controla-a daqui",
  "Suena en la app Spotifast {where}, con tu cuenta de Spotify Premium; kywai solo la maneja. Las luces del espacio no oyen este sonido.": "Toca na app Spotifast {where}, com a tua conta Spotify Premium; o kywai só a controla. As luzes do espaço não ouvem este som.",
