  "Con tu cuenta de YouTube: con Premium, sin anuncios.": "Com a tua conta do YouTube: sem anúncios com Premium.",
  "Con la sesión de YouTube de este navegador: con Premium, sin anuncios.": "Com a sessão do YouTube deste navegador: sem anúncios com Premium.",
