  "¿Tienes YouTube Premium? Inicia sesión con tu cuenta y sonará sin anuncios.": "Tens YouTube Premium? Inicia sessão com a tua conta e toca sem anúncios.",
  "¿Tienes YouTube Premium? Usa la sesión de YouTube de este navegador y sonará sin anuncios.": "Tens YouTube Premium? Usa a sessão do YouTube deste navegador e toca sem anúncios.",
  "No se inició sesión en YouTube.": "Não foi iniciada sessão no YouTube.",
  "Iniciar sesión en YouTube": "Iniciar sessão no YouTube",
  "Usar mi cuenta": "Usar a minha conta",
  "Entrar en YouTube": "Entrar no YouTube",
  "Ocultar la guía": "Ocultar o guia",
  "¿Cómo lo hago?": "Como faço?",
  "Guía: {title}": "Guia: {title}",
  "Pon la cuenta de Instagram de kywai en modo profesional: en la app de Instagram, Configuración → Tipo de cuenta → Creador o Empresa. Es gratis.": "Mude a conta do Instagram do kywai para profissional: no app do Instagram, Configurações → Tipo de conta → Criador ou Empresa. É grátis.",
  "Entra en developers.facebook.com → Mis apps → Crear app y elige el caso de uso «Administrar mensajes y contenido en Instagram» (si pregunta el tipo, «Empresa»).": "Entre em developers.facebook.com → Meus apps → Criar app e escolha o caso de uso “Gerenciar mensagens e conteúdo no Instagram” (se pedir o tipo, “Empresa”).",
  "Abrir Meta for Developers": "Abrir Meta for Developers",
  "Dentro de la app: Configuración de la API con inicio de sesión de Instagram → Generar identificadores de acceso → Añadir cuenta, e inicia sesión con el Instagram de kywai. Si llega una invitación de probador, acéptala en Instagram (Configuración → Apps y sitios web).": "Dentro do app: Configuração da API com login do Instagram → Gerar tokens de acesso → Adicionar conta, e entre com o Instagram do kywai. Se chegar um convite de testador, aceite-o no Instagram (Configurações → Apps e sites).",
  "Junto a la cuenta sale un número: es el ID de la cuenta. Pulsa «Generar identificador» y copia el texto largo que empieza por IG…: es el token de acceso.": "Ao lado da conta aparece um número: é o ID da conta. Toque em “Gerar token” e copie o texto longo que começa com IG…: é o token de acesso.",
  "Pega los dos aquí abajo y pulsa «Conectar». El token dura unos 60 días: cuando caduque, kywai te avisa al publicar y repites el paso anterior.": "Cole os dois aqui embaixo e toque em “Conectar”. O token dura cerca de 60 dias: quando expirar, o kywai avisa ao publicar e você repete o passo anterior.",
  "Nunca hace falta la contraseña de Instagram. No compartas el token con nadie (tampoco en un chat): kywai lo guarda cifrado.": "A senha do Instagram nunca é necessária. Não compartilhe o token com ninguém (nem em um chat): o kywai o guarda criptografado.",
  "Entra en developers.tiktok.com con la cuenta de TikTok de kywai → Manage apps → Connect an app.": "Entre em developers.tiktok.com com a conta do TikTok do kywai → Manage apps → Connect an app.",
  "Abrir TikTok for Developers": "Abrir TikTok for Developers",
  "Rellena el icono, el nombre, la descripción y la categoría. También pide la dirección de unos términos del servicio y de una política de privacidad.": "Preencha o ícone, o nome, a descrição e a categoria. Também pede o endereço de termos de serviço e de uma política de privacidade.",
  "En Platforms marca «Desktop». En Products añade «Login Kit» y «Content Posting API» (con «Direct Post» activado). En Scopes: user.info.basic, video.upload y video.publish.": "Em Platforms marque “Desktop”. Em Products adicione “Login Kit” e “Content Posting API” (com “Direct Post” ativado). Em Scopes: user.info.basic, video.upload e video.publish.",
  "En Login Kit → Desktop → Redirect URI pon esta dirección: {uri}": "Em Login Kit → Desktop → Redirect URI coloque este endereço: {uri}",
  "Mientras TikTok no revise la app, usa el Sandbox: crea uno, añade la cuenta de kywai en «Target users» y copia su Client key y Client secret (salen en «Credentials»).": "Enquanto o TikTok não revisar o app, use o Sandbox: crie um, adicione a conta do kywai em “Target users” e copie o Client key e o Client secret dele (ficam em “Credentials”).",
  "Pégalos aquí abajo y pulsa «Guardar». Luego «Iniciar sesión en TikTok», autoriza la cuenta de kywai y, cuando el navegador vaya a una página de localhost que no carga, copia esa dirección entera, pégala aquí y pulsa «Conectar».": "Cole-os aqui embaixo e toque em “Salvar”. Depois “Entrar no TikTok”, autorize a conta do kywai e, quando o navegador for para uma página de localhost que não carrega, copie esse endereço inteiro, cole aqui e toque em “Conectar”.",
  "Para publicar en público, pide la revisión de la app en developers.tiktok.com. Cuando la aprueben, pulsa «Desconectar» → «Cambiar la app», pega la clave y el secreto de producción (no los del Sandbox), vuelve a iniciar sesión y pulsa «TikTok ya aprobó la app».": "Para publicar em público, peça a revisão do app em developers.tiktok.com. Quando aprovarem, toque em “Desconectar” → “Trocar o app”, cole a chave e o segredo de produção (não os do Sandbox), entre de novo e toque em “O TikTok já aprovou o app”.",
  "Nunca hace falta la contraseña de TikTok. No compartas el Client secret con nadie (tampoco en un chat): kywai lo guarda cifrado.": "A senha do TikTok nunca é necessária. Não compartilhe o Client secret com ninguém (nem em um chat): o kywai o guarda criptografado.",
  "Cambiar la app": "Trocar o app",
  // «/editar» y «/recortes» (src/main/footage.ts)
