  "Quité {takes} palabras de tomas repetidas o arranques en falso, {fillers} muletillas y los silencios largos; cada corte lleva un fundido corto, la voz va limpia y nivelada y el color, retocado.": "Tirei {takes} palavras de tomadas repetidas ou começos em falso, {fillers} muletas e os silêncios longos; cada corte tem um fade curto, a voz está limpa e nivelada e a cor, retocada.",
