  "Tres portadas para tu vídeo (el adjunto o el último), con fotogramas suyos y texto que engancha": "Três capas para o seu vídeo (anexado ou o último), com quadros dele e texto que prende",
  "Publicando el reel de prueba en Instagram (tienes activado «Publicar sin preguntar»).": "Publicando o reel de teste no Instagram (você ativou «Publicar sem perguntar»).",
  "Reel de prueba listo: Instagram lo enseñará primero solo a quien no te sigue y, si funciona, a tus seguidores. Revisa el texto y pulsa «Publicar».": "Reel de teste pronto: o Instagram vai mostrá-lo primeiro só para quem não te segue e, se funcionar, para seus seguidores. Revise o texto e toque em «Publicar».",
  "Reel de prueba listo para Instagram{who}": "Reel de teste pronto para o Instagram{who}",
