  "Lo he guardado en {file}: desde ahora los guiones de «/video» y los textos de «/instagram» aprenden de lo que funcionó.": "Salvei em {file}: a partir de agora os roteiros do «/video» e os textos do «/instagram» aprendem com o que funcionou.",
  "Lo he guardado en {file}. Con 3 reels o más, los guiones y los textos empezarán a aprender de lo que funcionó.": "Salvei em {file}. Com 3 reels ou mais, roteiros e textos começam a aprender com o que funcionou.",
